#!/usr/bin/env python3
"""生成したファイルの直接の編集を拒否する PreToolUse の hook (プラグイン doc-structured)。

Edit・Write・NotebookEdit の対象のファイルが、ツール doc-structured で生成したファイルなら、編集が実行される前に拒否し、
直す元のファイル (生成元) と生成のコマンドを Claude に伝える。
  - 生成したファイルかどうかは、ファイル自身の先頭の記述で判定する。判定にはプラグインの中のモジュール
    tool/src/doc_structured/generated_header.py を使う (判定の規則はバージョンをまたいで変えないので、
    プロジェクトが設定したツールのバージョンと違っても結果は同じ)
  - プロジェクトの設定は読まない。検査も実行しない
  - まだ無いファイルと、先頭の記述の無いファイル (手書きのファイル) は拒否しない
  - Bash での編集と人のエディタでの編集は、この hook では防げない。検査 a が検出する

このスクリプトは、Python 3.12 より古い python3 でも構文の誤りにならないように書き、版を確認してからモジュールを読み込む。
古い python3 や読めない入力では判定をせず、標準エラー出力に理由を書いて終了コード 1 で終了する
(Claude Code は編集をそのまま実行する。古い Python の環境で、すべての編集を拒否しないため)。
"""

import json
import os
import sys

PLUGIN_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SKILL = "doc-structured:generate"


def error(message):
    sys.stderr.write("doc-structured: " + message + "\n")
    return 1


def deny(reason):
    output = {
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": reason,
        }
    }
    print(json.dumps(output, ensure_ascii=False))


def main():
    if sys.version_info < (3, 12):
        found = ".".join(str(n) for n in sys.version_info[:3])
        return error(
            "生成したファイルの編集を拒否する hook には Python 3.12 以上の python3 が要る (見つかったのは "
            + found + ")。生成したファイルかどうかを判定せずに、編集を実行させる"
        )
    sys.path.insert(0, os.path.join(PLUGIN_ROOT, "tool", "src"))
    from doc_structured import generated_header

    try:
        data = json.load(sys.stdin)
    except json.JSONDecodeError as e:
        return error(f"hook の入力を JSON として読めない ({e})。生成したファイルかどうかを判定せずに、編集を実行させる")
    if not isinstance(data, dict):
        return error("hook の入力が JSON のオブジェクトでない。生成したファイルかどうかを判定せずに、編集を実行させる")
    tool_input = data.get("tool_input") or {}
    if not isinstance(tool_input, dict):
        return error("hook の入力の tool_input が JSON のオブジェクトでない。生成したファイルかどうかを判定せずに、編集を実行させる")
    path = tool_input.get("file_path") or tool_input.get("notebook_path")
    if not path:
        return 0
    if not isinstance(path, str):
        return error("hook の入力の file_path か notebook_path が文字列でない。生成したファイルかどうかを判定せずに、編集を実行させる")
    cwd = data.get("cwd") or os.getcwd()
    full_path = os.path.join(cwd, path)
    if not os.path.isfile(full_path):
        return 0
    try:
        header = generated_header.read_file_header(full_path)
    except OSError as e:
        return error(f"{full_path} を読めない ({e})。生成したファイルかどうかを判定せずに、編集を実行させる")
    if header is None:
        return 0

    relative = os.path.relpath(full_path, cwd)
    # cwd の外かどうかはパスの要素で判定する (cwd の直下の「..cache」のような名前のディレクトリは cwd の中)
    outside = relative == os.pardir or relative.startswith(os.pardir + os.sep)
    shown = full_path if outside else relative
    command = header.command or generated_header.GENERATE_COMMAND
    if header.source:
        how = f"生成元 {header.source} を直し、スキル {SKILL} (コマンド {command}) で生成し直す"
    else:
        how = f"先頭の記述から生成元を読み取れなかった。生成元を直し、スキル {SKILL} (コマンド {command}) で生成し直す"
    deny(f"{shown} は doc-structured が生成したファイル (先頭に doc-structured:generated の記述がある) なので、直接編集しない。{how}。")
    return 0


if __name__ == "__main__":
    sys.exit(main())
"""生成したファイルの先頭の記述。

生成したファイルには、決まった文字列 doc-structured:generated で始まる 1 行のコメントを、ファイルの書式のコメントで書く。
  frontmatter の無い Markdown (1 行目):
    <!-- doc-structured:generated 生成元: <パス> コマンド: <コマンド> (このファイルを直接編集せず、生成元を直して生成し直す) -->
  frontmatter のある Markdown (frontmatter の中の 2 行目)・YAML (1 行目)・シェルスクリプト (shebang の次の 2 行目):
    # doc-structured:generated 生成元: <パス> コマンド: <コマンド> (このファイルを直接編集せず、生成元を直して生成し直す)
判定の規則 (バージョンをまたいで変えない): 先頭の 3 行の中に、HTML_PREFIX か HASH_PREFIX で始まる行があれば、生成したファイル。
生成元は、リポジトリのルートからの相対パス (複数の YAML から作るときはディレクトリで、末尾に「/」)。
形式の SSOT はプラグインの規則の文書 (ファイル doc-structured/rules/doc-structured-docs.md)。
sub-issue 3 の hook も、このモジュールで生成したファイルかどうかを判定する。
"""

import re
from dataclasses import dataclass
from pathlib import Path

MARKER = "doc-structured:generated"
HTML_PREFIX = f"<!-- {MARKER} "
HASH_PREFIX = f"# {MARKER} "
HEADER_LINES = 3
NOTE = "(このファイルを直接編集せず、生成元を直して生成し直す)"
GENERATE_COMMAND = "bin/doc-structured generate"

_FIELDS_RE = re.compile(r"生成元: (?P<source>\S+) コマンド: (?P<command>.+?) \(")


@dataclass(frozen=True)
class Header:
    source: str
    command: str


def _body(source: str, command: str) -> str:
    return f"{MARKER} 生成元: {source} コマンド: {command} {NOTE}"


def markdown_line(source: str, command: str = GENERATE_COMMAND) -> str:
    """frontmatter の無い Markdown の 1 行目。"""
    return f"<!-- {_body(source, command)} -->"


def hash_line(source: str, command: str = GENERATE_COMMAND) -> str:
    """YAML・シェルスクリプト・frontmatter の中に書く行。"""
    return f"# {_body(source, command)}"


def read_header(text: str) -> Header | None:
    """ファイルの内容から先頭の記述を読む。生成したファイルでなければ None。

    生成元とコマンドを取り出せないときも、生成したファイルとして扱い、空の文字列を入れて返す
    (判定の規則は先頭の文字列だけで、取り出せるかどうかに頼らないため)。
    """
    for line in text.splitlines()[:HEADER_LINES]:
        if line.startswith(HTML_PREFIX) or line.startswith(HASH_PREFIX):
            match = _FIELDS_RE.search(line)
            if match is None:
                return Header(source="", command="")
            return Header(source=match.group("source"), command=match.group("command"))
    return None


def read_file_header(path: str | Path) -> Header | None:
    """ファイルの先頭の HEADER_LINES 行を読み、先頭の記述を返す。生成したファイルでなければ None。

    ツールの generate と、プラグインの hook (hook-scripts/guard-generated.py) の両方がこの関数で判定する。
    文字コードは UTF-8 で、読めないバイトは置き換えて読む (判定に使うのは決まった ASCII の接頭辞だけのため)。
    ファイルを読めないときの OSError は、呼び出し元に渡す。
    """
    with open(path, encoding="utf-8", errors="replace") as f:
        head = "".join(f.readline() for _ in range(HEADER_LINES))
    return read_header(head)
"""サブコマンド check が実行する検査と、検査 a (生成し直して差分が無い)。

検査の群 (決定の一覧の問 12 (3)):
  軽い群 (--light。デフォルト)  文書と YAML だけで実行できる検査。この版では a・h・i
  重い群 (--heavy)              データベースなどが要る検査。この版には無い
--all は両方、--only <検査> は 1 つだけを実行する。
検査 h (YAML の形式) に誤りがあると、定義の一覧が正しく作れないので、検査 a と i は実行せず、そのことを報告する。
"""

import difflib
from dataclasses import dataclass, field
from pathlib import Path

from . import generated_header
from .direction import check_direction
from .domains import Project, load_project
from .generate import GITATTRIBUTES_PATH, HANDWRITTEN_MESSAGE, generated_files, handwritten_fix, render_project
from .problems import Problem

LIGHT = ("a", "h", "i")
HEAVY: tuple[str, ...] = ()
ALL = LIGHT + HEAVY


@dataclass
class CheckResult:
    checks: tuple[str, ...]  # 実行するよう指定された検査
    problems: list[Problem] = field(default_factory=list)
    skipped: list[str] = field(default_factory=list)  # 検査 h の誤りのため実行しなかった検査

    @property
    def ok(self) -> bool:
        return not self.problems and not self.skipped


def check_generated(root: Path, project: Project) -> list[Problem]:
    """検査 a: 生成し直した内容と、今のファイルを比べる。"""
    problems: list[Problem] = []
    outputs = render_project(project)
    for relative, expected in outputs.items():
        header = generated_header.read_header(expected)
        if relative == GITATTRIBUTES_PATH:
            # 内容は YAML ではなく生成したファイルの一覧から作るので、YAML を直す案内をしない
            how = (
                f"このファイルを直接編集せず、{header.command} を実行する。内容は生成したファイルの一覧から作る。"
                "手で属性を足すときは、リポジトリのルートの .gitattributes に書く"
            )
        else:
            how = f"このファイルを直接編集せず、生成元 {header.source} の YAML を直して {header.command} を実行する"
        path = root / relative
        if not path.is_file():
            problems.append(Problem("a", relative, f"生成するはずのファイルが無い。{header.command} を実行する"))
            continue
        if generated_header.read_file_header(path) is None:
            problems.append(Problem("a", relative, f"{HANDWRITTEN_MESSAGE}。{handwritten_fix(relative)}"))
            continue
        actual = path.read_text(encoding="utf-8")
        if actual == expected:
            continue
        diff = "".join(
            difflib.unified_diff(
                actual.splitlines(keepends=True),
                expected.splitlines(keepends=True),
                fromfile=f"{relative} (今のファイル)",
                tofile=f"{relative} (生成し直した内容)",
            )
        )
        problems.append(Problem("a", relative, f"生成し直した内容と違う。{how}", detail=diff))
    for relative, header in generated_files(root).items():
        if relative in outputs:
            continue
        if header.source and not (root / header.source).exists():
            message = f"生成元 {header.source} が無い。このファイルを消すか、生成元を戻す"
        else:
            command = header.command or generated_header.GENERATE_COMMAND
            message = f"生成し直すと消えるファイルが残っている。{command} を実行して消す"
        problems.append(Problem("a", relative, message))
    return problems


def run_checks(root: Path, checks: tuple[str, ...]) -> CheckResult:
    result = CheckResult(checks=checks)
    if not checks:
        return result
    project, yaml_problems = load_project(root)
    if "h" in checks:
        result.problems += yaml_problems
    if yaml_problems:
        result.skipped = [c for c in checks if c in ("a", "i")]
        return result
    if "i" in checks:
        result.problems += check_direction(project)
    if "a" in checks:
        result.problems += check_generated(root, project)
    return result

